from fastapi import FastAPI
import time
import asyncio

app = FastAPI()

# ✅ Plain def: FastAPI automatically offloads this to an anyio worker thread.
# The main event loop remains 100% responsive to other users!
@app.get('/safe-sync')
def sync_endpoint():
  time.sleep(5) # Runs on background threadpool
  return {'status': 'done'}

# ✅ True non-blocking async:
@app.get('/safe-async')
async def async_endpoint():
  await asyncio.sleep(5) # Non-blocking event loop pause
  return {'status': 'done'}
